package com.uzukip.gokapi.desktop.platform

import java.util.Properties

/** The build's `<versionBase>.<commit count>`, generated by desktop/build.gradle.kts. */
val appVersion: String by lazy {
    val stream = object {}.javaClass.getResourceAsStream("/gokapi-desktop/version.properties")
    stream?.use { Properties().apply { load(it) }.getProperty("version") } ?: "dev"
}
